ruleContent.content:
@js:
if(baseUrl.match(/\/album\//)){
let linksString = java.getString('[class="photos-list text-center"]@img@data-src');
linksString = linksString.replace("\r\n", "\n").replace("\r", "\n");
let linksArray = linksString.split("\n").filter(link => link.trim() !== "");
var imgTags = linksArray.map(link => `<img src="${link.trim()}" alt="Image">`).join("\n");
imgTags="&nbsp;"+imgTags;
}
imgTags;

