exploreUrl:
@js:
var result = [];
var push = (title, url, size) => result.push({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: size
  }
});
var tagul = org.jsoup.Jsoup.parse(java.ajax(source.key + "/category/")).select('.module li a');
for (i in tagul) {
    push(tagul[i].select('h4').text(),`/e/extend/more/lsmore.php?page={{page}}&line=10&cl=${Number(i)+1}`,0.45);
}
JSON.stringify(result);

ruleBookInfo.tocUrl:
@js:
var id = baseUrl.match(/(\d+).*?$/)[1];
var sr = java.ajax("http://www.ailcai.com" + org.jsoup.Jsoup.parse(src).select('.page_main script')[1].attr('src'));
result = sr.match(/url: "([^"]+)/)[1] + id + "&pageNum=0&dz=asc";

ruleToc.nextTocUrl:
@js:
var pages = JSON.parse(src).totalPage
var pagesList = [];
for (let i = 1; i < pages; i++) {
pagesList.push(baseUrl.replace("pageNum=0",`pageNum=${i}`));
}
pagesList;

